package com.pocketqc.distributed.model

import org.json.JSONObject

/**
 * Authoritative, immutable record of a physical item defect inspection event.
 * Generated by an inspection node (Device 2 / Device 3) and accepted by the server (Device 1).
 */
data class InspectionEvent(
    val eventId: String,
    val deviceId: String,
    val sessionId: String,
    val batchId: String,
    val stationName: String,
    val inspectionMode: String = "2D_DEFECT_SORT",
    val modelId: String = "biscuits_final",
    val modelVersion: String = "1.0",
    val itemId: String,
    val classId: Int,
    val className: String,
    val confidence: Float,
    val clientTimestampUtc: Long,
    val serverReceiptTimestampUtc: Long = System.currentTimeMillis(),
    val schemaVersion: Int = 1
) {
    init {
        require(eventId.isNotBlank()) { "eventId must not be blank" }
        require(deviceId.isNotBlank()) { "deviceId must not be blank" }
        require(sessionId.isNotBlank()) { "sessionId must not be blank" }
        require(batchId.isNotBlank()) { "batchId must not be blank" }
        require(className.isNotBlank()) { "className must not be blank" }
        require(confidence in 0.0f..1.0f && !confidence.isNaN()) {
            "confidence must be between 0.0 and 1.0 (got $confidence)"
        }
    }

    val isDefect: Boolean
        get() = className.equals("Broken", ignoreCase = true) ||
                className.equals("Fracture", ignoreCase = true) ||
                className.contains("Defect", ignoreCase = true) ||
                className.contains("Aflatoxin", ignoreCase = true) ||
                className.contains("FLAGGED", ignoreCase = true) ||
                className.contains("OUT_OF_TOLERANCE", ignoreCase = true) ||
                className.contains("REJECT", ignoreCase = true)

    val isPass: Boolean
        get() = !isDefect

    fun toJson(): JSONObject {
        return JSONObject().apply {
            put("eventId", eventId)
            put("deviceId", deviceId)
            put("sessionId", sessionId)
            put("batchId", batchId)
            put("stationName", stationName)
            put("inspectionMode", inspectionMode)
            put("modelId", modelId)
            put("modelVersion", modelVersion)
            put("itemId", itemId)
            put("classId", classId)
            put("className", className)
            put("confidence", confidence.toDouble())
            put("clientTimestampUtc", clientTimestampUtc)
            put("serverReceiptTimestampUtc", serverReceiptTimestampUtc)
            put("schemaVersion", schemaVersion)
        }
    }

    companion object {
        fun fromJson(json: JSONObject): InspectionEvent {
            return InspectionEvent(
                eventId = json.getString("eventId"),
                deviceId = json.getString("deviceId"),
                sessionId = json.getString("sessionId"),
                batchId = json.getString("batchId"),
                stationName = json.optString("stationName", "Unknown Station"),
                inspectionMode = json.optString("inspectionMode", "2D_DEFECT_SORT"),
                modelId = json.optString("modelId", "biscuits_final"),
                modelVersion = json.optString("modelVersion", "1.0"),
                itemId = json.getString("itemId"),
                classId = json.optInt("classId", 0),
                className = json.getString("className"),
                confidence = json.getDouble("confidence").toFloat(),
                clientTimestampUtc = json.getLong("clientTimestampUtc"),
                serverReceiptTimestampUtc = json.optLong("serverReceiptTimestampUtc", System.currentTimeMillis()),
                schemaVersion = json.optInt("schemaVersion", 1)
            )
        }
    }
}
